const $ = s => document.querySelector(s);
let lang = localStorage.getItem('aeris-language') === 'it' ? 'it' : 'en';
let inspection, selected = 'F-001', view = 'overview', backend = false, live = false, pending = false;
const translations = {
 en: {workspace:'Inspection workspace',operations:'OPERATIONS',overview:'Overview',findings:'Findings',telemetry:'Telemetry',reports:'Reports',sample:'Sample environment',independent:'Independent portfolio prototype. Not affiliated with Dronemaster.',engineer:'Software engineering portfolio',operationsTitle:'Operations',eyebrow:'FIELD INTELLIGENCE / INS-2026-042',subtitle:'Turn inspection evidence into decisions, in English and Italian.',export:'Export report',demoTag:'DEMO DATA',demoText:'Synthetic inspection · illustrative aerial schematic · no live aircraft connected',review:'Human review required',mission:'INSPECTION',complete:'Complete',location:'Valle Seriana, Italy',coverage:'AREA COVERAGE',coverageNote:'Simulated survey coverage',totalFindings:'FINDINGS TO REVIEW',findingCounts:'1 high · 1 medium · 1 low',duration:'MISSION DURATION',durationNote:'Sample flight log · 09:00–09:18',inspectionMap:'Inspection overview',mapSub:'Facility 04 · annotated evidence locations',schematic:'SCHEMATIC',illustrative:'ILLUSTRATIVE',surveyPath:'Sample survey path',copilot:'Inspection copilot',copilotTitle:'From evidence to understanding.',copilotIntro:'Explore this inspection. Every answer points back to its source.',questionLabel:'Ask about the inspection',chatNote:'Evidence only. Review recommendations with a qualified operator.',findingsTitle:'Findings register',findingsSub:'Traceable observations. Ready for human review.',filter:'Filter severity',observation:'OBSERVATION',severity:'SEVERITY',source:'EVIDENCE SOURCE',annotation:'SAMPLE SCORE',scoreNote:'Scores are synthetic annotations, not measured model accuracy.',telemetryTitle:'Mission telemetry',telemetrySub:'Battery, signal quality and ambient temperature · synthetic log',reportTitle:'Inspection report',reportSub:'English + Italian · evidence references included',download:'Download Markdown',footer:'Inspection intelligence, with evidence.'},
 it: {workspace:'Area di lavoro ispezioni',operations:'OPERAZIONI',overview:'Panoramica',findings:'Rilievi',telemetry:'Telemetria',reports:'Rapporti',sample:'Ambiente dimostrativo',independent:'Prototipo portfolio indipendente. Non affiliato a Dronemaster.',engineer:'Portfolio di ingegneria software',operationsTitle:'Operazioni',eyebrow:'ANALISI SUL CAMPO / INS-2026-042',subtitle:'Dai dati ispettivi alle decisioni, in italiano e in inglese.',export:'Esporta rapporto',demoTag:'DATI DEMO',demoText:'Ispezione sintetica · schema aereo illustrativo · nessun velivolo connesso',review:'Verifica umana necessaria',mission:'ISPEZIONE',complete:'Completata',location:'Valle Seriana, Italia',coverage:'COPERTURA AREA',coverageNote:'Copertura simulata del rilievo',totalFindings:'RILIEVI DA VERIFICARE',findingCounts:'1 alto · 1 medio · 1 basso',duration:'DURATA MISSIONE',durationNote:'Registro di esempio · 09:00–09:18',inspectionMap:'Panoramica ispezione',mapSub:'Impianto 04 · posizioni dei rilievi annotati',schematic:'SCHEMA',illustrative:'ILLUSTRATIVO',surveyPath:'Percorso di rilievo simulato',copilot:'Copilota ispettivo',copilotTitle:'Dai dati alla comprensione.',copilotIntro:'Esplora questa ispezione. Ogni risposta rimanda alla sua fonte.',questionLabel:'Fai una domanda sull’ispezione',chatNote:'Solo evidenze. Verificare i suggerimenti con un operatore qualificato.',findingsTitle:'Registro dei rilievi',findingsSub:'Osservazioni tracciabili, pronte per la verifica umana.',filter:'Filtra gravità',observation:'OSSERVAZIONE',severity:'GRAVITÀ',source:'FONTE DEI DATI',annotation:'PUNTEGGIO DEMO',scoreNote:'I punteggi sono annotazioni sintetiche, non misure di accuratezza del modello.',telemetryTitle:'Telemetria della missione',telemetrySub:'Batteria, qualità del segnale e temperatura ambiente · registro sintetico',reportTitle:'Rapporto di ispezione',reportSub:'Italiano + inglese · riferimenti alle evidenze inclusi',download:'Scarica Markdown',footer:'Analisi delle ispezioni, basata sui dati.'}
};
const titles={en:{overview:'Every finding. A clearer picture.',findings:'Evidence that speaks for itself.',telemetry:'The story behind the flight.',reports:'Two languages. One clear report.'},it:{overview:'Ogni rilievo. Un quadro più chiaro.',findings:'Evidenze che parlano da sole.',telemetry:'La storia dietro il volo.',reports:'Due lingue. Un rapporto chiaro.'}};
const severityName=s=>({en:{high:'High',medium:'Medium',low:'Low'},it:{high:'Alta',medium:'Media',low:'Bassa'}}[lang][s]);
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function renderLanguage(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(n=>n.textContent=translations[lang][n.dataset.i]||n.textContent);document.querySelectorAll('[data-lang]').forEach(n=>n.classList.toggle('selected',n.dataset.lang===lang));$('#question').placeholder=lang==='it'?'Chiedi di questa ispezione…':'Ask about this inspection…';$('#severity').options[0].text=lang==='it'?'Tutte le gravità':'All severities';['high','medium','low'].forEach((s,i)=>$('#severity').options[i+1].text=severityName(s));$('#mode-label').textContent=live?(lang==='it'?'AI attiva · risposte basate sui dati':'Live AI · evidence-grounded answers'):(lang==='it'?'Ricerca nelle evidenze · nessun modello AI':'Evidence search · no language model');$('#mode-badge').textContent=live?'AI':'DEMO';renderFindings();renderSelected();renderSuggestions();renderTelemetry();renderReport();setView(view);}
function renderFindings(){const filter=$('#severity').value;const rows=inspection.findings.filter(f=>filter==='all'||f.severity===filter);$('#finding-rows').replaceChildren(...rows.map(f=>{const tr=el('tr');tr.append(el('td',f.id),el('td',f.title[lang]));const sev=el('td');sev.append(el('span',severityName(f.severity),'severity-label '+f.severity));tr.append(sev,el('td',f.source));const score=el('td');const bar=el('span',undefined,'score-bar');const fill=el('i');fill.style.width=f.confidence+'%';bar.append(fill);score.append(bar,document.createTextNode(f.confidence+'%'));const action=el('td');const b=el('button','↗','row-open');b.setAttribute('aria-label',(lang==='it'?'Apri ':'Open ')+f.id);b.onclick=()=>selectFinding(f.id,true);action.append(b);tr.append(score,action);return tr;}));$('#visible-count').textContent=rows.length+(lang==='it'?' rilievi':' findings');$('#map-markers').replaceChildren(...inspection.findings.map((f,i)=>{const b=el('button',String(i+1),'marker '+f.severity+(selected===f.id?' selected':''));b.style.left=f.x+'%';b.style.top=f.y+'%';b.title=f.title[lang];b.setAttribute('aria-label',f.id+' '+f.title[lang]);b.onclick=()=>selectFinding(f.id);return b;}));}
function renderSelected(){const f=inspection.findings.find(f=>f.id===selected);const box=$('#selected-finding');box.replaceChildren(el('span',severityName(f.severity),'severity-label '+f.severity));const detail=el('div');detail.append(el('strong',f.title[lang]),el('p',f.id+' · '+f.source));const b=el('button','↗','finding-arrow');b.setAttribute('aria-label',lang==='it'?'Mostra evidenza':'Show evidence');b.onclick=()=>{addMessage(f.detail[lang],[f.id]);$('.copilot-panel').scrollIntoView({behavior:'smooth',block:'center'});};box.append(detail,b);}
function selectFinding(id,scroll=false){selected=id;renderSelected();renderFindings();if(scroll){setView('overview');$('#inspection-panel').scrollIntoView({behavior:'smooth',block:'center'});}}
function renderSuggestions(){const questions=lang==='it'?['Quali sono i rilievi prioritari?','Spiega l’anomalia termica','Cosa è successo al segnale?']:['Which findings need attention first?','Explain the thermal anomaly','What happened to the signal?'];$('#suggestions').replaceChildren(...questions.map(q=>{const b=el('button',q);b.onclick=()=>ask(q);return b;}));}
function addMessage(text,sources=[],user=false){const message=el('div',undefined,'chat-message'+(user?' user':''));message.append(el('span',user?(lang==='it'?'TU':'YOU'):(live?'AERIS AI':'AERIS · EVIDENCE'),'message-label'),document.createTextNode(text));if(sources.length){message.append(document.createElement('br'));sources.forEach(id=>{const b=el('button',id,'evidence-link');b.onclick=()=>selectFinding(id,true);message.append(b);});}$('#chat').append(message);$('.copilot-body').scrollTop=$('.copilot-body').scrollHeight;}
function searchEvidence(question,language){const q=question.toLowerCase();let records;if(/priorit|attention|urgent|summary|riepilog|sintesi|tutti|all finding/.test(q))records=inspection.findings;else if(/thermal|termic|b7|calor|heat|temperatur|hot/.test(q))records=inspection.findings.filter(f=>f.category==='thermal');else if(/signal|segnal|rete|radio/.test(q))records=inspection.findings.filter(f=>f.category==='telemetry');else if(/walkway|surface|damage|passerella|dann|superfic/.test(q))records=inspection.findings.filter(f=>f.category==='visual');else records=inspection.findings.filter(f=>q.includes(f.id.toLowerCase()));if(!records.length)return {answer:language==='it'?'Le evidenze disponibili non consentono di rispondere. Prova una domanda sull’anomalia termica, sulla passerella o sul segnale.':'The available evidence does not establish an answer. Try asking about the thermal anomaly, walkway or signal.',sources:[]};return {answer:records.map(f=>`${f.id}: ${f.detail[language]}`).join('\n\n'),sources:records.map(f=>f.id)};}
async function ask(q){if(pending)return;pending=true;const requestLanguage=lang;$('#send').disabled=true;$('#question').value='';addMessage(q,[],true);$('.copilot-intro').hidden=true;$('#suggestions').hidden=true;try{let result;if(backend){const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,language:requestLanguage}),signal:AbortSignal.timeout(45000)});if(!r.ok)throw new Error('request failed');result=await r.json();}else result=searchEvidence(q,requestLanguage);addMessage(result.answer,result.sources);}catch{addMessage(requestLanguage==='it'?'Richiesta non riuscita. Riprova; nessuna risposta AI è stata generata.':'The request failed. Please retry; no AI answer was generated.');}finally{pending=false;$('#send').disabled=false;}}
function reportMarkdown(){let text=`# AERIS — Inspection report / Rapporto di ispezione\n\n${inspection.id} | ${inspection.site} | ${inspection.date}\n\nSynthetic portfolio data. Independent prototype, not affiliated with Dronemaster.\nDati sintetici per portfolio. Prototipo indipendente, non affiliato a Dronemaster.\n\n`;for(const language of ['en','it']){text+=`## ${language==='en'?'English':'Italiano'}\n\n`;inspection.findings.forEach(f=>{text+=`### ${f.id} — ${f.title[language]}\n\n${f.detail[language]}\n\n${language==='en'?'Source':'Fonte'}: ${f.source}\n\n`;});}return text+'## Limitations / Limiti\n\nNo real image inference is performed. Findings and scores are pre-annotated synthetic examples. No aircraft control. All recommendations require qualified human review.\nNessuna analisi automatica di immagini reali. Rilievi e punteggi sono esempi sintetici preannotati. Nessun controllo di velivoli. Ogni suggerimento richiede verifica umana qualificata.\n';}
async function downloadReport(){const content=reportMarkdown();const blob=new Blob([content],{type:'text/markdown;charset=utf-8'});const a=el('a');a.href=URL.createObjectURL(blob);a.download=inspection.id+'-EN-IT.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(lang==='it'?'Rapporto bilingue esportato':'Bilingual report exported');if(backend)fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).catch(()=>{});}
function renderReport(){$('#report-preview').replaceChildren(...['en','it'].map(language=>{const div=el('div');div.append(el('h3',language==='en'?'English':'Italiano'));inspection.findings.forEach(f=>{div.append(el('h4',f.id+' · '+f.title[language]),el('p',f.detail[language]),el('small',f.source));});return div;}));}
function renderTelemetry(){const container=$('#telemetry-chart');container.replaceChildren();const legend=el('div',undefined,'telemetry-legend');const series=[['battery',lang==='it'?'Batteria %':'Battery %','#648d4e'],['signal',lang==='it'?'Segnale %':'Signal %','#b69d5e'],['temperature',lang==='it'?'Temperatura °C':'Temperature °C','#8b9eaa']];series.forEach(([,label,color])=>{const n=el('span',label);n.style.color=color;legend.append(n);});container.append(legend);const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 850 250');svg.setAttribute('class','chart-svg');svg.setAttribute('role','img');svg.setAttribute('aria-label',translations[lang].telemetrySub);function node(tag,attrs,text){const n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text)n.textContent=text;svg.append(n);}for(let v=0;v<=100;v+=25){const y=215-v*1.8;node('line',{x1:38,y1:y,x2:820,y2:y,stroke:'#e8eddf'});node('text',{x:3,y:y+4,fill:'#97a28b','font-size':10},String(v));}series.forEach(([key,,color])=>node('polyline',{points:inspection.telemetry.map((p,i)=>`${40+i*128},${215-p[key]*1.8}`).join(' '),fill:'none',stroke:color,'stroke-width':2.5}));inspection.telemetry.forEach((p,i)=>node('text',{x:40+i*128,y:242,fill:'#97a28b','font-size':10,'text-anchor':'middle'},p.time));container.append(svg);}
function setView(next){view=next;$('#page-title').textContent=titles[lang][view];$('#breadcrumb-view').textContent=translations[lang][view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('.main-grid').hidden=view!=='overview';$('#findings-panel').hidden=!['overview','findings'].includes(view);$('#telemetry-panel').hidden=view!=='telemetry';$('#report-panel').hidden=view!=='reports';}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('aeris-language',lang);renderLanguage();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#severity').onchange=renderFindings;$('#export').onclick=downloadReport;$('#download-report').onclick=downloadReport;$('#chat-form').onsubmit=e=>{e.preventDefault();const q=$('#question').value.trim();if(q)ask(q);};
async function init(){try{const r=await fetch('/api/inspection',{signal:AbortSignal.timeout(2500)});if(r.ok&&r.headers.get('content-type')?.includes('application/json')){const data=await r.json();if(data.inspection){inspection=data.inspection;backend=true;live=data.ai_enabled;}}}catch{}if(!inspection){const r=await fetch('sample.json');if(!r.ok)throw new Error('sample unavailable');inspection=await r.json();}renderLanguage();}
init().catch(()=>toast('Could not load inspection data. Please reload.'));
